import subprocess, os, pty, select, time

# REPL needs tty for both stdin and stdout? Our capture pipes stdout, so repl detects piped output and errors.
# Need to test REPL via pty to see behavior.
# Let's try using pty.

import subprocess, os, pty, time, select

def test_repl(commands, timeout=3):
    # commands: list of strings to send (each with newline)
    master, slave = pty.openpty()
    proc = subprocess.Popen(["./executable", "--repl"], stdin=slave, stdout=slave, stderr=slave, text=True, bufsize=0)
    os.close(slave)
    output = b""
    # read initial output
    time.sleep(0.5)
    # drain
    import fcntl
    fl = fcntl.fcntl(master, fcntl.F_GETFL)
    fcntl.fcntl(master, fcntl.F_SETFL, fl | os.O_NONBLOCK)
    try:
        while True:
            try:
                data = os.read(master, 4096)
                if not data:
                    break
                output += data
            except BlockingIOError:
                break
    except Exception as e:
        print(f"read err {e}")
    print(f"initial output: {output!r}")
    for cmd in commands:
        print(f"sending: {cmd!r}")
        os.write(master, (cmd+"\n").encode())
        time.sleep(0.5)
        try:
            while True:
                try:
                    data = os.read(master, 4096)
                    if not data:
                        break
                    output += data
                    print(f"  read chunk: {data!r}")
                except BlockingIOError:
                    break
        except Exception as e:
            print(f"read err {e}")
    # send Ctrl-D / exit?
    try:
        os.write(master, b"\x04")
        time.sleep(0.5)
        try:
            while True:
                try:
                    data = os.read(master, 4096)
                    if not data:
                        break
                    output += data
                    print(f"  final chunk: {data!r}")
                except BlockingIOError:
                    break
        except: pass
    except: pass
    proc.terminate()
    try:
        proc.wait(timeout=2)
    except: proc.kill()
    os.close(master)
    print(f"full output: {output!r}")
    print(f"exit: {proc.returncode}")

test_repl(['"hi";', '2 of "a";', ':exit'])
PY
"}

