import subprocess, os, pty, time, fcntl

def test_repl(commands, extra_args=[], timeout=3):
    master, slave = pty.openpty()
    proc = subprocess.Popen(["./executable"]+extra_args, stdin=slave, stdout=slave, stderr=slave, text=True, bufsize=0)
    os.close(slave)
    output = b""
    time.sleep(0.5)
    fl = fcntl.fcntl(master, fcntl.F_GETFL)
    fcntl.fcntl(master, fcntl.F_SETFL, fl | os.O_NONBLOCK)
    def drain(label=""):
        nonlocal output
        try:
            while True:
                try:
                    data = os.read(master, 4096)
                    if not data:
                        break
                    output += data
                    print(f"{label} chunk: {data!r}")
                except BlockingIOError:
                    break
        except Exception as e:
            print(f"read err {e}")
    drain("initial")
    for cmd in commands:
        print(f"sending: {cmd!r}")
        os.write(master, (cmd+"\n").encode())
        time.sleep(0.5)
        drain("after cmd")
    proc.terminate()
    try:
        proc.wait(timeout=2)
    except: proc.kill()
    try: os.close(master)
    except: pass
    print(f"exit: {proc.returncode}")
    return output

# Test more REPL commands: undo, redo, clear, source, exit variants, invalid input, empty, etc.
print("=== test undo/redo/clear/source ===")
test_repl(['"a";', '"b";', ':s', ':u', ':s', ':r', ':s', ':c', ':s', ':e'])
