{"command":"python3 <<'PY'
import subprocess

def run_raw(args, inp=None):
    r = subprocess.run(["./executable"]+args, input=inp, capture_output=True, timeout=5)
    return r

def t(src):
    r = run_raw(["-"], inp=src.encode())
    print(f"SRC={src!r} => exit={r.returncode} stdout={r.stdout!r} stderr={r.stderr.decode(errors='ignore')!r}")

# Test literal escaping exhaustive
import string
for ch in string.printable:
    if ch in ['\n','\r','\x0b','\x0c','\t',' ']:
        continue
    # Test literal with single char ch inside double quotes: need to escape " and \ for input?
    # For ch = '"', input is '"\\"";' (escaped quote). For ch = '\\', input is '"\\\\";'
    # For others, input is f'"{ch}";'
    if ch == '"':
        src = '"\\"";'
    elif ch == '\\':
        src = '"\\\\";'
    else:
        src = f'"{ch}";'
    r = run_raw(["-"], inp=src.encode())
    if r.returncode==0:
        print(f"char {ch!r} src={src!r} => {r.stdout!r}")
    else:
        print(f"char {ch!r} src={src!r} => ERR {r.stderr.decode(errors='ignore').strip()!r}")

PY
