import subprocess

def run_raw(args, inp=None):
    r = subprocess.run(["./executable"]+args, input=inp, capture_output=True, timeout=5)
    return r

# Good. So escapes: \" only in double, \' only in single, \\ \/ \b \f \n \r \t \uXXXX in both.
# What about other escapes like \v \0 \x etc? All fail (we saw). Let's confirm \v \0 fail in both?
for esc in ["\\v", "\\0", "\\x41", "\\c", "\\d", "\\s", "\\w", "\\u", "\\u12", "\\u123", "\\u12345"]:
    for q in ['"', "'"]:
        src = f"{q}{esc}{q};"
        r = run_raw(["-"], inp=src.encode())
        print(f"src={src!r} => exit={r.returncode} stdout={r.stdout!r}")

# Test raw allowed chars: raw is `...` with no backslash, no backtick? Let's brute force raw single-char content.
import string
for ch in string.printable:
    if ch in ['\n','\r','\x0b','\x0c']:
        continue
    # raw content is ch inside backticks: f"`{ch}`;"
    # For ch = "`", input would be "```;" (empty + ...)? Actually "`" inside raw would end raw. So test separately.
    # For ch = "\\", input is "`\\`;" which we saw fails.
    # For ch = "`", input "```;"? Let's see: "`" + "`" + "`" + ";"? That's `` + `;? Hmm.
    if ch == "`":
        src = "```;"
    elif ch == "\\":
        src = "`\\`;"
    else:
        src = f"`{ch}`;"
    r = run_raw(["-"], inp=src.encode())
    if r.returncode==0:
        print(f"raw char {ch!r} => {r.stdout!r}")
    else:
        print(f"raw char {ch!r} => ERR")
