    let full = pair.as_str();
    let inner = &full[1..full.len()-1];
    Ok(normalize_crlf(inner))
}

fn compile_range(pair: pest::iterators::Pair<Rule>) -> Result<String, String> {
    // range = { ascii_range_start ~ "to" ~ ascii_range_end }, inner is two ascii_range_* pairs
    let mut inner = pair.into_inner();
    let start = inner.next().unwrap();
    let end = inner.next().unwrap();
    let s = start.as_str();
    let e = end.as_str();
    // s and e are single ASCII chars (single byte? Could be control? Assume single char)
