    }
}

fn compile_group(pair: pest::iterators::Pair<Rule>, vars: &mut HashMap<String, String>, src: &str) -> Result<String, String> {
    // group_declaration = { "match" ~ block | "either" ~ block | "capture" ~ identifier* ~ block }
    let s = pair.as_str();
    let trimmed = s.trim_start();
    if trimmed.starts_with("match") {
        // inner is block (single)
        let block = pair.into_inner().next().unwrap();
        let content = compile_block(block, vars, src)?;
        Ok(format!("(?:{})", content))
    } else if trimmed.starts_with("either") {
        let block = pair.into_inner().next().unwrap();
        let content = compile_block_either(block, vars, src)?;
        Ok(format!("(?:{})", content))
    } else if trimmed.starts_with("capture") {
        // inner is identifier* + block (block last)
        let mut inners: Vec<pest::iterators::Pair<Rule>> = pair.into_inner().collect();
        // Last is block, rest are identifiers (possibly zero)
        let block = inners.pop().unwrap();
        debug_assert_eq!(block.as_rule(), Rule::block);
        if inners.is_empty() {
            let content = compile_block(block, vars, src)?;
            Ok(format!("({})", content))
        } else {
            // Reconstruct name with original spacing preserved (between identifiers)
            // inners are identifier pairs in order
            // Need src (processed source) to extract gaps? Actually pair spans are relative to processed input (which is same byte length as original for capture regions, since no // there). Good.
            // For each consecutive pair, gap = src[prev_end..next_start] as is (including spaces/tabs/newlines), normalized \r\n to \n?
            // Then name = first_ident + gap1 + second_ident + gap2 + ... (trimmed? No leading/trailing, since first starts after "capture" + ws, last ends before block "{" + ws, gaps only between)
            // Our inners' as_str() are identifiers without surrounding ws. Gaps are original ws between.
            let mut name = String::new();
            for (idx, ident_pair) in inners.iter().enumerate() {
                if idx > 0 {
                    let prev = &inners[idx-1];
                    let curr = ident_pair;
                    let prev_end = prev.as_span().end();
                    let curr_start = curr.as_span().start();
                    if curr_start > prev_end {
                        // Extract from src (processed) bytes? src is &str, need byte slicing. Spans are byte indices. Good.
                        let gap = &src[prev_end..curr_start];
                        let gap_norm = normalize_crlf(gap);
                        name.push_str(&gap_norm);
                    } else {
                        name.push(' ');
                    }
                }
                name.push_str(ident_pair.as_str());
            }
            let content = compile_block(block, vars, src)?;
            Ok(format!("(?<{}>{})", name, content))
        }
    } else {
        unreachable!()
    }
}

