fn compile_quantifier(pair: pest::iterators::Pair<Rule>, vars: &mut HashMap<String, String>, src: &str) -> Result<String, String> {
    // quantifier_quantity = { quantifier ~ quantifier_target }, inner: quantifier, quantifier_target
    let mut q_inner = pair.into_inner();
    let quant = q_inner.next().unwrap();
    let target = q_inner.next().unwrap();
    debug_assert_eq!(quant.as_rule(), Rule::quantifier);
    debug_assert_eq!(target.as_rule(), Rule::quantifier_target);
    // Parse quantifier: check lazy, type, amounts
    let quant_str = quant.as_str();
    let quant_trimmed = quant_str.trim_start();
    let is_lazy = quant_trimmed.starts_with("lazy");
    // quant inner is quantifier_inner (single)
    let qinner = quant.into_inner().next().unwrap();
    debug_assert_eq!(qinner.as_rule(), Rule::quantifier_inner);
    let qinner_str = qinner.as_str();
    let qinner_trimmed = qinner_str.trim_start();
    // Collect amounts in order
    let amounts: Vec<String> = qinner.clone().into_inner().filter(|p| p.as_rule() == Rule::amount).map(|p| p.as_str().to_string()).collect();
    // Determine suffix and validate
    let suffix: String;
    if qinner_trimmed.starts_with("some") {
        suffix = "+".to_string();
    } else if qinner_trimmed.starts_with("any") {
        suffix = "*".to_string();
    } else if qinner_trimmed.starts_with("option") {
        suffix = "?".to_string();
    } else if qinner_trimmed.starts_with("over") {
        // over N of => {N+1,}
        let n_str = &amounts[0];
        let k = inc_numeric(n_str);
        suffix = format!("{{{},}}", k);
    } else {
        // numeric: either N of or N to M of
        // Check if contains "to" (as keyword)? qinner_str contains "to" with possible spaces? For "5 to 10 of", contains "to". For "5 of", does not.
        // But need to be careful: amounts could be like "5", "10", etc. If amounts.len()==2, then N to M of, else N of.
        if amounts.len() == 2 {
            let n_str = &amounts[0];
            let m_str = &amounts[1];
            if cmp_numeric(n_str, m_str) == std::cmp::Ordering::Greater {
                return Err("usage of an invalid quantifier range".to_string());
            }
            suffix = format!("{{{},{}}}", n_str, m_str);
        } else {
            let n_str = &amounts[0];
            suffix = format!("{{{}}}", n_str);
        }
    }
    let mut full_suffix = suffix;
    if is_lazy {
        full_suffix.push('?');
    }
    // Compile target
    // quantifier_target = { group_declaration | assertion_declaration | variable_declaration | literal ~ ";" | raw ~ ";" | not | range ~ ";" | variable_invocation ~ ";" }
    // inner is single child (one of those), but for literal ~ ";" etc., inner includes literal + ";"? Actually ";" is anonymous, not in inner. So for "literal ~ ';'", inner is just literal. Similarly raw, range, var_inv.
    // For not (which already includes ";" for non-assertion), inner is not (single).
    // For group/assertion/var_decl, inner is single.
    let target_inner = target.into_inner().next().unwrap();
    match target_inner.as_rule() {
        Rule::group_declaration => {
            let g = compile_group(target_inner, vars, src)?;
            Ok(format!("{}{}", g, full_suffix))
        }
        Rule::assertion_declaration => {
            return Err("unexpected assertion in quantifier".to_string());
