// Color helpers: colors enabled if stdout is tty and not no-color
// For errors (stderr), color based on stdout tty (as observed), not stderr tty.
fn use_color(no_color: bool) -> bool {
    if no_color {
        return false;
    }
    std::io::stdout().is_terminal()
}

fn color_blue(s: &str, use_color: bool) -> String {
    if use_color {
        format!("\x1b[94m{}\x1b[0m", s)
    } else {
        s.to_string()
    }
}
fn color_red(s: &str, use_color: bool) -> String {
    if use_color {
        format!("\x1b[91m{}\x1b[0m", s)
    } else {
        s.to_string()
    }
}
fn color_green(s: &str, use_color: bool) -> String {
    if use_color {
        format!("\x1b[92m{}\x1b[0m", s)
    } else {
        s.to_string()
    }
}
fn color_bright_blue(s: &str, use_color: bool) -> String {
    // Same as blue (94)
    color_blue(s, use_color)
}
fn color_dim(s: &str, use_color: bool) -> String {
    if use_color {
        format!("\x1b[2m{}\x1b[0m", s)
    } else {
        s.to_string()
    }
}

fn truncate_test(s: &str) -> String {
    // Truncate to 10 chars + "..." if len > 10 chars (Unicode chars, not bytes)
    let char_count = s.chars().count();
    if char_count > 10 {
        let truncated: String = s.chars().take(10).collect();
        format!("{}...", truncated)
    } else {
        s.to_string()
    }
}

