import subprocess, pty, os, time, fcntl
def run_repl(binary, commands, extra_args=[]):
    master, slave = pty.openpty()
    proc = subprocess.Popen([binary]+extra_args, stdin=slave, stdout=slave, stderr=slave)
    os.close(slave)
    time.sleep(0.5)
    fl = fcntl.fcntl(master, fcntl.F_GETFL)
    fcntl.fcntl(master, fcntl.F_SETFL, fl | os.O_NONBLOCK)
    out=b""
    def drain():
        nonlocal out
        try:
            while True:
                try:
                    data = os.read(master, 4096)
                    if not data: break
                    out+=data
                except BlockingIOError: break
        except: pass
    drain()
    for cmd in commands:
        os.write(master, (cmd+"\n").encode())
        time.sleep(0.4)
        drain()
    try: proc.wait(timeout=2)
    except:
        proc.terminate()
        try: proc.wait(timeout=2)
        except: proc.kill()
    drain()
    try: os.close(master)
    except: pass
    return proc.returncode, out
